import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Header from './components/Header';
import HowItWorks from './components/HowItWorks';
import ImageWithButton from './components/ImageWithButton';
import PostJobSection from './components/PostJobSection';
import Features from './components/Features';
import Footer from './components/Footer';
import MainPage from './components/MainPage'; // Import MainPage
import './App.css';

const App = () => {
  return (
    <Router>
      <div className="app">
        <Routes>
          <Route
            path="/"
            element={
              <>
                <Header />
                <HowItWorks />
                <ImageWithButton />
                <PostJobSection />
                <Features />
                <Footer />
              </>
            }
          />
          <Route path="/main" element={<MainPage />} /> {/* Route for MainPage */}
        </Routes>
      </div>
    </Router>
  );
};

export default App;
